result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/metagen/src/meta.js", "content": "import * as cheerio from 'cheerio';

const DESCRIPTION_LIMIT = 155;

/**
 * Escape a value for safe interpolation into a double-quoted HTML attribute.
 */
export function escapeAttr(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/**
 * Truncate a description to at most 155 characters on a word boundary,
 * leaving no dangling space or trailing comma.
 */
export function truncateDescription(description, limit = DESCRIPTION_LIMIT) {
  const text = String(description ?? '');
  if (text.length <= limit) return text;

  let cut = text.slice(0, limit);
  // Back off to the last word boundary so we never cut mid-word.
  const lastBoundary = Math.max(
    cut.lastIndexOf(' '),
    cut.lastIndexOf('\n'),
    cut.lastIndexOf('\t'),
  );
  if (lastBoundary > 0) cut = cut.slice(0, lastBoundary);

  // Trim any dangling separators/whitespace left at the end.
  return cut.replace(/[\s,;:.\-–—]+$/u, '');
}

/**
 * Render social meta tags (Open Graph + Twitter cards), canonical link,
 * title element, and meta description.
 */
export function renderMeta({ title, description, url, image, siteName, type } = {}) {
  const desc = truncateDescription(description);

  const lines = [];
  if (title != null) lines.push(`<title>${escapeHtml(title)}</title>`);
  if (desc) lines.push(`<meta name="description" content="${escapeAttr(desc)}">`);

  if (title != null) lines.push(`<meta property="og:title" content="${escapeAttr(title)}">`);
  if (desc) lines.push(`<meta property="og:description" content="${escapeAttr(desc)}">`);
  if (url != null) lines.push(`<meta property="og:url" content="${escapeAttr(url)}">`);
  if (image != null) lines.push(`<meta property="og:image" content="${escapeAttr(image)}">`);
  if (siteName != null) lines.push(`<meta property="og:site_name" content="${escapeAttr(siteName)}">`);
  lines.push(`<meta property="og:type" content="${escapeAttr(type ?? 'website')}">`);

  const card = image != null ? 'summary_large_image' : 'summary';
  lines.push(`<meta name="twitter:card" content="${card}">`);
  if (title != null) lines.push(`<meta name="twitter:title" content="${escapeAttr(title)}">`);
  if (desc) lines.push(`<meta name="twitter:description" content="${escapeAttr(desc)}">`);
  if (image != null) lines.push(`<meta name="twitter:image" content="${escapeAttr(image)}">`);

  if (url != null) lines.push(`<link rel="canonical" href="${escapeAttr(url)}">`);

  return lines.join('\n');
}

function escapeHtml(value) {
  return escapeAttr(value);
}

/**
 * Parse an HTML document back into the meta object renderMeta consumes.
 */
export function parseMeta(html) {
  const $ = cheerio.load(html);

  const content = (selector) => $(selector).attr('content');
  const og = (property) => content(`meta[property="og:${property}"]`);
  const tw = (name) => content(`meta[name="twitter:${name}"]`);

  const meta = {};
  const title = $('title').first().text();
  if (title) meta.title = title;

  const description = $('meta[name="description"]').attr('content') ?? og('description');
  if (description != null) meta.description = description;

  const url = $('link[rel="canonical"]').attr('href') ?? og('url');
  if (url != null) meta.url = url;

  const image = og('image') ?? tw('image');
  if (image != null) meta.image = image;

  const siteName = og('site_name');
  if (siteName != null) meta.siteName = siteName;

  const type = og('type');
  if (type != null) meta.type = type;

  return meta;
}
