result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/metagen/test/meta.test.js", "content": "import { describe, it, expect } from 'vitest';
import { renderMeta, parseMeta, truncateDescription } from '../src/meta.js';

const canonicalInput = {
  title: 'My Great Page',
  description: 'A concise summary of the page contents.',
  url: 'https://example.com/page',
  image: 'https://example.com/img/cover.png',
  siteName: 'Example Site',
  type: 'article',
};

describe('renderMeta / parseMeta round-trip', () => {
  it('inverts back to the original object for a fully-specified input', () => {
    const html = renderMeta(canonicalInput);
    expect(parseMeta(html)).toEqual(canonicalInput);
  });

  it('round-trips values containing characters that need escaping', () => {
    const input = {
      title: 'He said "hello" & <goodbye>',
      description: 'Quotes " and ampersands & survive',
      url: 'https://example.com/a?b=1&c=2',
      image: 'https://example.com/i.png',
      siteName: 'Q&A Site',
      type: 'website',
    };
    expect(parseMeta(renderMeta(input))).toEqual(input);
  });

  it('emits the standard og pairs, title element, meta description and canonical link', () => {
    const html = renderMeta(canonicalInput);
    expect(html).toContain('<title>My Great Page</title>');
    expect(html).toContain('<meta name="description" content="A concise summary of the page contents.">');
    expect(html).toContain('<meta property="og:title" content="My Great Page">');
    expect(html).toContain('<meta property="og:description"');
    expect(html).toContain('<meta property="og:url" content="https://example.com/page">');
    expect(html).toContain('<meta property="og:image" content="https://example.com/img/cover.png">');
    expect(html).toContain('<meta property="og:site_name" content="Example Site">');
    expect(html).toContain('<meta property="og:type" content="article">');
    expect(html).toContain('<link rel="canonical" href="https://example.com/page">');
  });
});

describe('truncation', () => {
  it('truncates a 200-char description to <=155 chars on a word boundary', () => {
    // Build a deterministic 200-char description of words.
    const words = ['lorem', 'ipsum', 'dolor', 'sit', 'amet', 'consectetur', 'adipiscing'];
    let long = '';
    while (long.length < 200) long += (long ? ' ' : '') + words[Math.floor(Math.random() * words.length)];
    const desc200 = long.slice(0, 200);

    expect(desc200.length).toBe(200);

    const truncated = truncateDescription(desc200);
    expect(truncated.length).toBeLessThanOrEqual(155);
    expect(truncated.length).toBeGreaterThan(0);
    // No mid-word cut: result must be a prefix of the original ending on whitespace.
    expect(desc200.startsWith(truncated)).toBe(true);
    expect(desc200[truncated.length]).toBe(' ');
    // No dangling space/comma.
    expect(truncated.endsWith(' ')).toBe(false);
    expect(truncated.endsWith(',')).toBe(false);
  });

  it('leaves short descriptions untouched', () => {
    const short = 'Short and sweet';
    expect(truncateDescription(short)).toBe(short);
  });

  it('renderMeta uses the truncated description in all description slots', () => {
    const words = Array.from({ length: 60 }, (_, i) => `word${i}`);
    const long = words.join(' ').slice(0, 200);
    const html = renderMeta({ ...canonicalInput, description: long });
    const parsed = parseMeta(html);
    expect(parsed.description.length).toBeLessThanOrEqual(155);
    expect(parsed.description).toBe(truncateDescription(long));
  });
});

describe('escaping', () => {
  it('escapes double quotes in the title attribute values', () => {
    const html = renderMeta({ ...canonicalInput, title: 'The "Best" Page' });
    // Raw quote must not appear unescaped inside an attribute.
    expect(html).toContain('content="The &quot;Best&quot; Page"');
    expect(html).not.toContain('The "Best"');
    // And parsing recovers the original value.
    expect(parseMeta(html).title).toBe('The "Best" Page');
  });

  it('escapes ampersands, angle brackets and single quotes', () => {
    const html = renderMeta({
      title: `Tom's & <Jerry's> "Show"`,
      description: 'ok',
      url: 'https://example.com/x?a=1&b=2',
    });
    expect(html).toContain('&amp;');
    expect(html).toContain('&#39;');
    expect(html).toContain('&lt;');
    expect(html).not.toMatch(/<Jerry|'/);
  });
});

describe('twitter card switching', () => {
  it('uses summary_large_image when an image is present', () => {
    const html = renderMeta(canonicalInput);
    expect(html).toContain('<meta name="twitter:card" content="summary_large_image">');
    expect(html).toContain('<meta name="twitter:image" content="https://example.com/img/cover.png">');
  });

  it('falls back to summary without an image', () => {
    const { image, ...noImage } = canonicalInput;
    const html = renderMeta(noImage);
    expect(html).toContain('<meta name="twitter:card" content="summary">');
    expect(html).not.toContain('summary_large_image');
    expect(html).not.toContain('twitter:image');
    expect(parseMeta(html)).toEqual(noImage);
  });

  it('switches card type based solely on image presence', () => {
    const withImage = renderMeta({ ...canonicalInput, image: undefined });
    const backToImage = renderMeta(withImage === null ? canonicalInput : { ...canonicalInput });
    expect(withImage).toContain('"summary"');
    expect(backToImage).toContain('"summary_large_image"');
  });
});
"})
